owner(); c=Client(); project=c.identity(); idle(probe(c))
code=r'''
var paths=new[]{"Assets/Prefabs/Enemy/Enemy_Zombie.prefab","Assets/_UIAssets/Monsters/Giants/Zombie/Zombie.prefab"};
var controller=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEditor.Animations.AnimatorController>("Assets/_UIAssets/Monsters/_Common/Animations/Giant/Controller.controller");
System.Func<UnityEngine.Object,object> reference=o=> {if(!o)return null;string guid;long id;UnityEditor.AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out guid,out id);return new {name=o.name,path=UnityEditor.AssetDatabase.GetAssetPath(o),guid=guid,fileID=id};};
System.Func<UnityEditor.Animations.AnimatorStateTransition,object> transition=t=>new {t.name,destination=t.destinationState?t.destinationState.name:null,destinationStateMachine=t.destinationStateMachine?t.destinationStateMachine.name:null,t.isExit,t.duration,t.offset,t.hasExitTime,t.exitTime,t.hasFixedDuration,t.canTransitionToSelf,t.orderedInterruption,interruptionSource=t.interruptionSource.ToString(),t.mute,t.solo,conditions=t.conditions.Select(q=>new{q.parameter,mode=q.mode.ToString(),q.threshold}).ToArray()};
System.Func<UnityEditor.Animations.AnimatorStateMachine,object> machine=null;
machine=m=>new {m.name,defaultState=m.defaultState?m.defaultState.name:null,states=m.states.Select(s=>new{s.state.name,motion=reference(s.state.motion),s.state.speed,s.state.speedParameter,s.state.speedParameterActive,s.state.cycleOffset,s.state.cycleOffsetParameter,s.state.cycleOffsetParameterActive,s.state.mirror,s.state.mirrorParameter,s.state.mirrorParameterActive,s.state.iKOnFeet,s.state.writeDefaultValues,s.state.tag,transitions=s.state.transitions.Select(transition).ToArray()}).ToArray(),anyStateTransitions=m.anyStateTransitions.Select(transition).ToArray(),entryTransitions=m.entryTransitions.Select(t=>new{t.name,destination=t.destinationState?t.destinationState.name:null,t.isExit,t.mute,t.solo,conditions=t.conditions.Select(q=>new{q.parameter,mode=q.mode.ToString(),q.threshold}).ToArray()}).ToArray(),children=m.stateMachines.Select(s=>machine(s.stateMachine)).ToArray()};
return Newtonsoft.Json.JsonConvert.SerializeObject(new {
hierarchies=paths.Select(p=>{var g=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.GameObject>(p);return new {path=p,nodes=g.GetComponentsInChildren<UnityEngine.Transform>(true).Select(t=>{var sr=t.GetComponent<UnityEngine.SpriteRenderer>();var receiver=t.GetComponent<FTProject.MonsterAnimEventReceiver>();return new{path=UnityEditor.AnimationUtility.CalculateTransformPath(t,g.transform),t.name,active=t.gameObject.activeSelf,position=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},rotation=new[]{t.localEulerAngles.x,t.localEulerAngles.y,t.localEulerAngles.z},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z},components=t.GetComponents<UnityEngine.Component>().Select(x=>x?x.GetType().FullName:"MISSING").ToArray(),renderer=sr?new{enabled=sr.enabled,order=sr.sortingOrder,sr.flipX,sr.flipY,sprite=reference(sr.sprite)}:null,receiver=receiver?new{head=receiver.HeadRenderer?receiver.HeadRenderer.name:null,sprites=receiver.HeadSprites==null?null:receiver.HeadSprites.Select(reference).ToArray()}:null};}).ToArray()};}).ToArray(),
parameters=controller.parameters.Select(p=>new{p.name,type=p.type.ToString(),p.defaultInt,p.defaultFloat,p.defaultBool}).ToArray(),
layers=controller.layers.Select(l=>new{l.name,l.defaultWeight,blendingMode=l.blendingMode.ToString(),l.iKPass,l.syncedLayerIndex,l.syncedLayerAffectsTiming,stateMachine=machine(l.stateMachine)}).ToArray(),
clips=controller.animationClips.Distinct().Select(a=>new{path=UnityEditor.AssetDatabase.GetAssetPath(a),a.name,a.length,a.frameRate,loop=UnityEditor.AnimationUtility.GetAnimationClipSettings(a).loopTime,settings=UnityEditor.AnimationUtility.GetAnimationClipSettings(a),events=UnityEditor.AnimationUtility.GetAnimationEvents(a).Select(e=>new{e.time,e.functionName,e.intParameter,e.floatParameter,e.stringParameter,messageOptions=e.messageOptions.ToString(),objectReference=reference(e.objectReferenceParameter)}).ToArray(),floatCurves=UnityEditor.AnimationUtility.GetCurveBindings(a).Select(b=>{var curve=UnityEditor.AnimationUtility.GetEditorCurve(a,b);return new{b.path,b.propertyName,type=b.type.FullName,preWrapMode=curve.preWrapMode.ToString(),postWrapMode=curve.postWrapMode.ToString(),keys=curve.keys.Select((k,i)=>new{k.time,k.value,k.inTangent,k.outTangent,k.inWeight,k.outWeight,weightedMode=k.weightedMode.ToString(),leftTangentMode=UnityEditor.AnimationUtility.GetKeyLeftTangentMode(curve,i).ToString(),rightTangentMode=UnityEditor.AnimationUtility.GetKeyRightTangentMode(curve,i).ToString(),broken=UnityEditor.AnimationUtility.GetKeyBroken(curve,i)}).ToArray()};}).ToArray(),pptrCurves=UnityEditor.AnimationUtility.GetObjectReferenceCurveBindings(a).Select(b=>new{b.path,b.propertyName,type=b.type.FullName,keys=UnityEditor.AnimationUtility.GetObjectReferenceCurve(a,b).Select(k=>new{k.time,value=reference(k.value)}).ToArray()}).ToArray()}).ToArray()});
'''
contract=unwrap(c.tool('execute_code',{'action':'execute','code':code}))
save(HERE/'source_animation_contract_complete_20261029.json',{'observed_at':now(),'project':project,'contract':contract,'protocol_history':c.history})
t=target();serial={}
for key in ['source','battle']:
 p=ROOT/t[key];serial[key]={'path':t[key],'sha256':sha(p),'objects':[{'class_id':int(m[1]),'file_id':int(m[2]),'yaml':m[3]} for m in re.finditer(r'^--- !u!(\d+) &(-?\d+)\s*\n(.*?)(?=^--- !u!|\Z)',p.read_text(encoding='utf-8-sig'),re.M|re.S)]}
save(HERE/'original_serialized_objects_20261029.json',serial)
dest=HERE/'reference/exact_original_animation_contract';dest.mkdir()
for p in (ROOT/t['controller']).parent.iterdir():
 if p.is_file() and (p.suffix in ['.anim','.controller'] or p.name.endswith(('.anim.meta','.controller.meta'))):shutil.copy2(p,dest/p.name)
cache='var t=System.Linq.Enumerable.FirstOrDefault(System.Linq.Enumerable.Select(System.AppDomain.CurrentDomain.GetAssemblies(),a=>a.GetType("MCPForUnity.Editor.Services.EditorStateCache")),x=>x!=null);if(t!=null){var m=t.GetMethod("ForceUpdate",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);if(m!=null)m.Invoke(null,new object[]{"Zombie source factual snapshot"});}return true;'
c.tool('execute_code',{'action':'execute','code':cache});state=c.resource('mcpforunity://editor/state')
save(HERE/'unity_source_ready_20261029.json',{'observed_at':now(),'state':state,'probe':probe(c),'protocol_history':c.history})
